"use client";

import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import type { ArtPair } from "@/lib/content/sections";
import { useSiteText } from "@/components/site-text-context";
import { HomeArt } from "./HomeArt";
import styles from "./Homepage.module.css";

type HouseSlide = { id: string; art: ArtPair; title: string; body: string; ctaLabel: string; ctaHref: string; eyebrow?: string };

export function HouseSlideshow({ slides, variant = "story", isPageTitle = false }: {
  slides: readonly HouseSlide[]; variant?: "hero" | "story" | "wardrobe" | "stores"; isPageTitle?: boolean;
}) {
  const [index, setIndex] = useState(0);
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const [stopped, setStopped] = useState(false);
  const [reduced, setReduced] = useState(false);
  const start = useRef<{ x: number; y: number } | null>(null);
  const dragged = useRef(false);
  const text = useSiteText();
  const count = slides.length;
  const active = count ? index % count : 0;
  const move = (direction: number) => setIndex((i) => (i + direction + count) % count);

  useEffect(() => {
    const preference = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(preference.matches);
    update(); preference.addEventListener("change", update);
    return () => preference.removeEventListener("change", update);
  }, []);
useEffect(() => {
    if (count < 2 || stopped || hovered || focused || reduced || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const timer = setInterval(() => setIndex((i) => (i + 1) % count), 8000);
    return () => clearInterval(timer);
  }, [count, stopped, hovered, focused, reduced]);

  if (!count) return null;
  const slide = slides[active]!;
  const Heading = isPageTitle ? "h1" : "h2";
  const label = text[`home.label.${variant}`];

  return <section className={`${styles.slideshow} ${styles[variant]}`} aria-roledescription="carousel" aria-label={label}
    onMouseEnter={() => setHovered(true)} onMouseLeave={() => { setHovered(false); start.current = null; }}
    onFocusCapture={() => setFocused(true)} onBlurCapture={(e) => { if (!e.currentTarget.contains(e.relatedTarget)) setFocused(false); }}
    onKeyDown={(e) => { if (e.key === "ArrowRight") { e.preventDefault(); move(1); } if (e.key === "ArrowLeft") { e.preventDefault(); move(-1); } }}>
    <div className={styles.slideTop}><span className={styles.kicker}>{label}</span><span className={styles.edition}>{text["home.edition"].toUpperCase()}</span></div>
    <div className={styles.slideBody}>
      <Link href={slide.ctaHref} className={styles.slideImage} aria-label={`Explore ${slide.title}`}
        onPointerDown={(e) => { start.current = { x: e.clientX, y: e.clientY }; dragged.current = false; }}
        onPointerUp={(e) => { const origin = start.current; start.current = null; if (!origin) return; const delta = e.clientX - origin.x;
          if (Math.abs(delta) > 50 && Math.abs(delta) > Math.abs(e.clientY - origin.y)) { dragged.current = true; move(delta < 0 ? 1 : -1); } }}
        onPointerCancel={() => { start.current = null; }}
        onClickCapture={(e) => { if (dragged.current) { e.preventDefault(); dragged.current = false; } }}
        onDragStart={(e) => e.preventDefault()}>
        <HomeArt key={slide.id} art={slide.art} alt={slide.title} priority={variant === "hero" && active === 0} className={styles.slideArt} />
        <span className={styles.imageIndex} aria-hidden="true">{String(active + 1).padStart(2, "0")} / {String(count).padStart(2, "0")}</span>
      </Link>
      <div className={styles.slideCopy}>
        <div className={styles.slideWords} key={slide.id} aria-live={focused || stopped ? "polite" : "off"}>
          <span className={styles.kicker}>{slide.eyebrow || label}</span>
          <Heading className={styles.slideTitle}>{slide.title}</Heading>
          <p className={styles.body}>{slide.body}</p>
          <Link href={slide.ctaHref} className={styles.textLink}>{slide.ctaLabel}<span aria-hidden="true">↗</span></Link>
        </div>
        {count > 1 && <div className={styles.slideControls}>
          <div className={styles.slideDots}>{slides.map((item, i) => <button key={item.id} type="button" aria-label={`Show ${variant === "stores" ? item.ctaLabel : item.title}`}
            aria-pressed={active === i} onClick={() => setIndex(i)} className={styles.slideDot}><span>{String(i + 1).padStart(2, "0")}</span></button>)}</div>
          <div className={styles.arrows}>
            <button type="button" onClick={() => setStopped((value) => !value)} aria-label={stopped ? "Play slideshow" : "Pause slideshow"} aria-pressed={stopped} className={styles.arrow}>{stopped ? "▷" : "Ⅱ"}</button>
            <button type="button" onClick={() => move(-1)} aria-label="Previous slide" className={styles.arrow}>←</button>
            <button type="button" onClick={() => move(1)} aria-label="Next slide" className={styles.arrow}>→</button>
          </div>
        </div>}
      </div>
    </div>
  </section>;
}
